from typing import List

from .message_handling import (Structure, SMessageHeader, SBrowserObject, SMessageAddress,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from .sack_reflection_interface import EReportingMode, EBrowserObjectName

MAX_NUM_OF_ITEMS_IN_RADIOLINK_LIST_ACK_MSG = 128


@register_message
class BrowserRadioLinkListReq(RequestMessage):
    id = 0x1b4c

    _fields_ = [
        ('header', SMessageHeader),
        ('reportingMode', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('subsystem', SBrowserObject),
        ('browserObject', SBrowserObject),
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserRadioLinkListReq, self).__init__(board, cpu, *args, **kwargs)
        user_id = kwargs['user_id']

        self.reportingMode = EReportingMode.EReportingMode_Single
        self.contextId = user_id
        self.procedureId = 0  # ?
        self.subsystem.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.subsystem.objectId = board
        self.browserObject.objectName = EBrowserObjectName.EBrowserObjectName_User
        self.browserObject.objectId = user_id


class SBrowserRadioLink(Structure):
    _fields_ = [
        ('radioLink', SBrowserObject),
        ('radioLinkState', u32),
        ('radioLinkAddr', SMessageAddress)
    ]


class RadioLinkListDataInput(Structure):
    _fields_ = [
        ('userId', u32),
    ]


@register_message
class BrowserRadioLinkListAck(ResponseMessage):
    id = 0x1b4d

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('radioLinkCountTotal', u32),
        ('radioLinkCountInThisMessage', u32),
        ('radioLinkList', SBrowserRadioLink * MAX_NUM_OF_ITEMS_IN_RADIOLINK_LIST_ACK_MSG)
    ]


class BrowserRadioLinkListQuery(Query):
    def __init__(self, req, resp):
        super(BrowserRadioLinkListQuery, self).__init__(req, resp)

        self.radio_link_list = []
        self._actual_count = 0
        self._expected_total_count = 0

    def _handle_response(self):
        self._expected_total_count = self.resp_msg.radioLinkCountTotal
        count_in_this_message = self.resp_msg.radioLinkCountInThisMessage
        self._actual_count += count_in_this_message
        for rl in self.resp_msg.radioLinkList[:count_in_this_message]:
            self.radio_link_list.append(rl.get_copy())

    def _decide_if_complete(self):
        if self._actual_count == self._expected_total_count:
            self.complete = True


class RadioLinkListInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_radio_link_ids(self, board, cpu, user_id):
        # type: (int, int, int) -> List[int]
        query = BrowserRadioLinkListQuery(
            BrowserRadioLinkListReq(board, cpu, user_id=user_id),
            BrowserRadioLinkListAck()
        )

        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()

        radio_link_ids = []
        for radio_link in query.radio_link_list:
            radio_link_ids.append(int(radio_link.radioLink.objectId))

        return sorted(radio_link_ids)
